class CommandExecutionError(Exception):
    """
    Raised when given command is not executed successfully.
    """
    pass


class PIDNotFound(Exception):
    """
    Raised when PID not found for given process name.
    """
    pass


class TopologyNotFound(Exception):
    """
    Raised when topology for particular baseband module was not found.
    """
    pass


class CPUIdError(Exception):
    """
    Raised when incorrect CPU ID has been used.
    """
    pass


class SmodIpNotReachable(Exception):
    """
    Raised when SMOD IP is not reachable.
    """
    pass
